 "content": "from collections import deque


def transform(grid):
    """Expand each 2 inside a solid 3-panel into a 3x3 marker."""
    h, w = len(grid), len(grid[0])
    seen = set()
    panel_boxes = []

    # The panels are large connected fields of 3. Their bounding boxes include
    # positions occupied by the 2 markers that puncture each panel.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if len(cells) >= 8:
                rs = [p[0] for p in cells]
                cs = [p[1] for p in cells]
                panel_boxes.append((min(rs), max(rs), min(cs), max(cs)))

    targets = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1
                                        for r0, r1, c0, c1 in panel_boxes):
                targets.append((r, c))

    out = [row[:] for row in grid]
    for r, c in targets:
        for rr in range(max(0, r - 1), min(h, r + 2)):
            for cc in range(max(0, c - 1), min(w, c + 2)):
                out[rr][cc] = 1
    # All original markers remain visible, including unrelated markers outside panels.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
    return out


if __name__ == '__main__':
    import json
    import sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))
